import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:pdf/widgets.dart' as pw;

class AppLogo {
  static const String base64Data = '';
  static Uint8List? _cachedBytes;

  static Uint8List get bytes {
    _cachedBytes ??= base64Decode(base64Data);
    return _cachedBytes!;
  }

  static pw.MemoryImage get pdfImage => pw.MemoryImage(bytes);

  static Widget widget({
    double? width,
    double? height,
    BoxFit fit = BoxFit.contain,
    double borderRadius = 0,
    BoxShape shape = BoxShape.rectangle,
  }) {
    Widget img = Image.memory(bytes, width: width, height: height, fit: fit, gaplessPlayback: true);
    if (shape == BoxShape.circle) return ClipOval(child: img);
    if (borderRadius > 0) return ClipRRect(borderRadius: BorderRadius.circular(borderRadius), child: img);
    return img;
  }
}
